  appendFigures("孝文帝迁都洛阳", "494", ["tuobahong"]);
  appendFigures("庆历新政", "1043", ["fanzhongyan", "ouyangxiu"]);
  appendFigures("活字印刷术", "1041", ["bisheng"]);
  appendFigures("陈桥兵变，北宋建立", "960", ["zhaokuangyin"]);
  appendFigures("戊戌变法", "1898", ["yangshenxiu"]);
  appendFigures("洋务运动开始", "1861", ["zengguofan", "zhangzhidong"]);
  appendFigures("武昌起义，辛亥革命", "1911", ["yuanshikai"]);

  D.sources.push(
    { label: "中国国家博物馆", url: "https://www.chnmuseum.cn/" },
    { label: "中国历史地图集", url: "https://zh.wikipedia.org/wiki/%E4%B8%AD%E5%9B%BD%E5%8E%86%E5%8F%B2%E5%9C%B0%E5%9B%BE%E9%9B%86" },
    { label: "江山时序历史地图", url: "https://github.com/DeanChensj/jiangshan-map" }
  );
